	@Test
	void clearPreservesSharedWriterAbortContract(@TempDir Path directory) throws Exception {
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(directory.toFile());
		try {
			PersistentSet<Long> first = createSet(factory, "first");
			PersistentSet<Long> second = createSet(factory, "second");
			first.add(1L);
			second.add(2L);
			factory.commit();
			first.remove(1L);
			second.add(3L);
			first.clear();
			assertTrue(contents(first).isEmpty());
			assertEquals(Set.of(2L), contents(second), "clear must still discard the shared staged writer");
			second.clear();
			assertTrue(contents(second).isEmpty());
			assertEquals(0, factory.writeTxn);
		} finally {
			factory.close();
		}
	}

	@Test
	void duplicateBulkAndIteratorMutationsUseActualContents(@TempDir Path directory) throws Exception {
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(directory.toFile());
		try {
			PersistentSet<Long> set = createSet(factory, "values");
			assertTrue(set.addAll(Set.of(1L, 2L, 3L)));
			assertFalse(set.add(1L));
			assertFalse(set.remove(99L));
			Iterator<Long> iterator = set.iterator();
			while (iterator.hasNext()) {
				iterator.next();
				iterator.remove();
			}
			factory.commit();
			long before = committedTransactionId(factory);
			set.clear();
			assertEquals(before, committedTransactionId(factory));
			set.addAll(Set.of(4L, 5L, 6L));
			set.removeAll(Set.of(4L));
			set.retainAll(Set.of(6L));
			factory.commit();
			assertEquals(Set.of(6L), contents(set));
			set.clear();
			assertTrue(contents(set).isEmpty());
		} finally {
			factory.close();
		}
	}

	@Test
	void consumedClearCommitFailureKeepsRowsAndSupportsRetry(@TempDir Path directory) throws Exception {
		ConsumingOperations operations = new ConsumingOperations();
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(directory.toFile(), operations);
		try {
			PersistentSet<Long> set = createSet(factory, "values");
			set.add(1L);
			factory.commit();
			long before = committedTransactionId(factory);
			operations.failNextCommit = true;
			RuntimeException failure = assertThrows(RuntimeException.class, set::clear);
			assertEquals(mdb_strerror(MDB_MAP_FULL), failure.getCause().getMessage());
			assertEquals(0, factory.writeTxn, "native commit failure has consumed the handle");
			assertEquals(0, operations.abortCalls, "cleanup must not reabort the consumed writer");
			assertEquals(before, committedTransactionId(factory));
			assertEquals(Set.of(1L), contents(set), "the real aborted commit must preserve prior contents");
			set.clear();
			assertEquals(before + 1, committedTransactionId(factory));
			assertTrue(contents(set).isEmpty());
			set.add(2L);
			factory.commit();
			assertEquals(Set.of(2L), contents(set), "a fresh writer must make real progress after failure");
		} finally {
			factory.close();
		}
		assertEquals(0, operations.abortCalls, "close must not abort a released writer");
	}

