	@Test
	void emptyAbortFailureReleasesHandleAndRetainsCause(@TempDir Path directory) throws Exception {
		ConsumingOperations operations = new ConsumingOperations();
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(directory.toFile(), operations);
		try {
			PersistentSet<Long> set = createSet(factory, "values");
			operations.failNextAbort = true;
			RuntimeException failure = assertThrows(RuntimeException.class, set::clear);
			assertSame(operations.abortFailure, failure.getCause());
			assertEquals(0, factory.writeTxn);
			assertEquals(1, operations.abortCalls, "failure cleanup must not reabort the consumed writer");
			set.add(3L);
			factory.commit();
			assertEquals(Set.of(3L), contents(set));
		} finally {
			factory.close();
		}
		assertEquals(1, operations.abortCalls);
	}

	private static PersistentSet<Long> createSet(PersistentSetFactory<Long> factory, String name) throws Exception {
		return factory.createSet(name, value -> ByteBuffer.allocate(Long.BYTES).putLong(value).array(),
				buffer -> buffer.order(ByteOrder.BIG_ENDIAN).getLong());
	}

	private static Set<Long> contents(PersistentSet<Long> set) {
		Set<Long> contents = new LinkedHashSet<>();
		for (Long value : set) {
			contents.add(value);
		}
		return contents;
	}

	private static final class ConsumingOperations implements PersistentSetFactory.NativeTransactionOperations {
		private boolean failNextCommit;
		private boolean failNextAbort;
		private int abortCalls;
		private final IllegalStateException abortFailure = new IllegalStateException("injected consumed abort failure");

		@Override
		public int commit(long transaction) {
			if (failNextCommit) {
				failNextCommit = false;
				mdb_txn_abort(transaction);
				return MDB_MAP_FULL;
			}
			return mdb_txn_commit(transaction);
		}

		@Override
		public void abort(long transaction) {
			abortCalls++;
			mdb_txn_abort(transaction);
			if (failNextAbort) {
				failNextAbort = false;
				throw abortFailure;
			}
		}
	}

	private static long committedTransactionId(PersistentSetFactory<?> factory) throws Exception {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(factory.env, info));
			return info.me_last_txnid();
		}
	}
